const choices=(a,v)=>a.map(x=>`<option ${x==v?'selected':''}>${E(x)}</option>`).join(''), fld=(n,l,t='text',v='',x='')=>`<label class="${t==='textarea'?'full':''}">${l}${t==='textarea'?`<textarea name="${n}" ${x}>${E(v)}</textarea>`:`<input name="${n}" type="${t}" value="${E(v)}" ${x}>`}</label>`, sel=(n,l,a,v)=>`<label>${l}<select name="${n}">${choices(a,v)}</select></label>`;
