function formTools(form,tools={}){const bar=document.createElement('div');bar.className='form-tools full';bar.innerHTML=`<button type="button" data-form-template ${tools.templates?.length?'':'disabled'}>Выбрать шаблон</button><button type="button" data-form-previous ${tools.previous?'':'disabled'}>Повторить предыдущую запись</button><button type="button" data-form-linked ${tools.linked?'':'disabled'}>Заполнить из связанной записи</button><button type="button" data-form-clear>Очистить форму</button>`;$('#entityFields').prepend(bar);bar.querySelector('[data-form-template]').onclick=()=>{const list=tools.templates||[],answer=prompt(`Выберите шаблон:\n${list.map((x,i)=>`${i+1}. ${x.name}`).join('\n')}`,'1');if(answer===null)return;const item=list[Number(answer)-1];if(item)fillForm(form,item.data,item.name);else notify('Шаблон не выбран')};bar.querySelector('[data-form-previous]').onclick=()=>fillForm(form,tools.previous?.(), 'Предыдущая запись');bar.querySelector('[data-form-linked]').onclick=()=>fillForm(form,tools.linked?.(), 'Связанная запись');bar.querySelector('[data-form-clear]').onclick=()=>{if(confirm('Очистить все введённые поля формы?'))[...form.elements].filter(x=>x.name).forEach(x=>{if(x.tagName==='SELECT')x.selectedIndex=0;else x.value=''})}}
function flow(title,html,done,tools){const d=$('#entityDialog'),f=$('#entityForm');d.dataset.mode='enterprise';$('#entityTitle').textContent=title;$('#entityFields').innerHTML=html;if(tools)formTools(f,tools);f.onsubmit=e=>{e.preventDefault();if(!f.checkValidity())return f.reportValidity();if(done(Object.fromEntries(new FormData(f)))!==false)d.close()};d.showModal()}
