function bindAppointmentDoctors(){const f=$('#entityForm'),branch=f.elements.branch,direction=f.elements.direction,doctor=f.elements.doctor;if(!branch||!direction||!doctor)return;const update=()=>{const previous=doctor.value,list=appointmentDoctors(branch.value,direction.value);doctor.innerHTML=list.map(x=>`<option>${E(x.name)}</option>`).join('');if(list.some(x=>x.name===previous))doctor.value=previous;doctor.disabled=!list.length;if(!list.length)notify('Для выбранного филиала и направления нет доступных специалистов')};branch.addEventListener('change',update);direction.addEventListener('change',update);update()}
function timeMinutes(value){const [h,m]=String(value).split(':').map(Number);return h*60+m}
