function cash(){const shift=state.shift,summary=shiftSummary(),history=state.cashShifts.slice(0,5);return `<section class="card fiscal-banner"><div><b>${shift?`Кассовая смена №${shift.number}`:'Кассовая смена закрыта'}</b><p>${shift?`${E(shift.cashier)} · открыта ${new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(shift.openedAt))} · начальный остаток ${M(shift.openingBalance)}`:'Откройте смену для проведения платежей и кассовых операций'}</p></div><span class="status ${shift?'success':'danger'}">${shift?'● Активна':'● Закрыта'}</span></section><section class="card"><div class="module-toolbar">${shift?`<button data-cash-deposit>＋ Внесение</button><button data-cash-withdraw>− Изъятие</button><button class="primary" data-close-shift>Закрыть смену</button>`:`<button class="primary" data-open-shift>Открыть смену</button>`}</div></section>${sectionShell([['Ожидаемо в кассе',shift?M(summary.expected):'—','наличный остаток'],['Наличная выручка',shift?M(summary.cash):'—','платежи'],['Безналичная выручка',shift?M(summary.card+summary.qr+summary.other):'—','карты, QR, другое'],['Смешанные',shift?summary.payments.filter(x=>x.method==='Смешанная').length:'—','операций'],['Возвраты',shift?M(summary.refunds):'—','за смену'],['Внесения / изъятия',shift?`${M(summary.deposits)} / ${M(summary.withdrawals)}`:'—','движения кассы']],`<section class="card"><div class="card-title"><div><h2>Операции текущей смены</h2><p>Только фактически сохранённые платежи и движения денег</p></div></div><div class="table-wrap"><table><thead><tr><th>Дата</th><th>Документ</th><th>Клиент / основание</th><th>Операция</th><th>Способ</th><th>Сумма</th></tr></thead><tbody>${shift?[...summary.payments.map(x=>({at:x.date,doc:x.orderId?`Заказ №${x.orderId}`:'—',subject:x.client,type:x.type,method:x.method,amount:(x.type==='Возврат'?-1:1)*Number(x.amount||0)})),...summary.movements.map(x=>({at:new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(x.at)),doc:x.number,subject:x.reason,type:x.type,method:'Наличные',amount:(x.type==='Изъятие'?-1:1)*Number(x.amount||0)}))].map(x=>`<tr><td>${E(x.at)}</td><td>${E(x.doc)}</td><td>${E(x.subject)}</td><td>${E(x.type)}</td><td>${E(x.method)}</td><td><b>${x.amount<0?'−':''}${M(Math.abs(x.amount))}</b></td></tr>`).join('')||'<tr><td colspan="6">Операций пока нет</td></tr>':'<tr><td colspan="6">Смена закрыта</td></tr>'}</tbody></table></div></section><section class="card"><div class="card-title"><div><h2>История закрытых смен</h2></div></div><div class="table-wrap"><table><thead><tr><th>Смена</th><th>Кассир</th><th>Открыта / закрыта</th><th>Выручка</th><th>Ожидалось</th><th>Фактически</th><th>Расхождение</th></tr></thead><tbody>${history.map(x=>`<tr><td>№${x.number}</td><td>${E(x.cashier)}</td><td>${E(new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(x.openedAt)))}<small>${E(new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(x.closedAt)))}</small></td><td>${M(x.turnover)}</td><td>${M(x.expectedCash)}</td><td>${M(x.actualCash)}</td><td><b>${x.discrepancy>0?'+':''}${M(x.discrepancy)}</b></td></tr>`).join('')||'<tr><td colspan="7">Закрытых смен пока нет</td></tr>'}</tbody></table></div></section>`)}`}
