function changeProcurementStatus(id){const p=state.procurements.find(x=>x.id===+id),allowed=PROCUREMENT_STATUSES.filter(x=>!['Получено'].includes(x));const answer=prompt(`Текущий статус: ${p.status}\n\nВыберите новый статус:\n${allowed.map((x,i)=>`${i+1}. ${x}`).join('\n')}`);if(answer===null)return;const next=allowed[Number(answer)-1];if(!next||next===p.status)return;if(next==='Отменено'&&!confirm(`Отменить закупку ${p.number}?`))return;p.status=next;p.history.unshift({at:new Date().toISOString(),status:next,note:'Статус изменён сотрудником'});put('procurements');renderModule();notify(`Статус ${p.number}: ${next}`)}
function receiveProcurement(id){const p=state.procurements.find(x=>x.id===+id),open=p.items.filter(x=>Number(x.receivedQty||0)<Number(x.qty));if(!open.length){notify('Все позиции уже получены');return}flow(`Приёмка ${p.number}`,`${open.map((x,i)=>{const product=state.catalog.find(y=>y.id===x.productId),remaining=x.qty-Number(x.receivedQty||0);return `<h3 class="full">${E(x.name)} · осталось ${remaining}</h3>${fld(`qty${i}`,'Принято','number',remaining,`required min="0" max="${remaining}"`)}${product?.serial?fld(`serials${i}`,'Серийные номера через запятую','textarea','',''):''}`}).join('')}${fld('comment','Комментарий приёмки','textarea','')}`,v=>{const received=[];for(let i=0;i<open.length;i++){const line=open[i],qty=Number(v[`qty${i}`]||0),product=state.catalog.find(x=>x.id===line.productId);if(!qty)continue;let serials=[];if(product.serial){serials=String(v[`serials${i}`]||'').split(',').map(x=>x.trim()).filter(Boolean);if(serials.length!==qty){notify(`Для «${product.name}» укажите ${qty} серийных номеров`);return false}if(serials.some(serial=>state.serialUnits.some(x=>x.serial===serial))){notify('Один из серийных номеров уже существует');return false}}received.push({line,product,qty,serials})}if(!received.length){notify('Укажите принятое количество');return false}const receiptId=Date.now(),receiptNumber=`IN-${String(receiptId).slice(-6)}`;received.forEach(({line,product,qty,serials})=>{line.receivedQty=Number(line.receivedQty||0)+qty;product.stock=Number(product.stock||0)+qty;product.purchasePrice=line.price;serials.forEach((serial,index)=>state.serialUnits.unshift({id:receiptId+index+product.id,serial,product:product.name,direction:product.direction||product.category,location:p.warehouse,status:'В наличии',client:'—',events:[[D(),'Поступление',receiptNumber]]}))});const progress=procurementProgress(p);p.status=progress.received>=progress.ordered?'Получено':'Частично поставлено';p.history.unshift({at:new Date().toISOString(),status:p.status,note:`${receiptNumber}: ${received.map(x=>`${x.product.name} × ${x.qty}`).join(', ')}${v.comment?' · '+v.comment:''}`});state.invoices.unshift({id:receiptId,name:receiptNumber,type:'Приход',procurementId:p.id,supplier:p.supplier,warehouse:p.warehouse,responsible:p.responsible,items:received.map(x=>({productId:x.product.id,name:x.product.name,qty:x.qty,price:x.line.price,serials:x.serials})),amount:M(received.reduce((s,x)=>s+x.qty*x.line.price,0)),status:'Проведена',createdAt:new Date().toISOString()});put('procurements');put('invoices');put('catalog');put('serialUnits');if(p.status==='Получено'&&p.orderId){const order=state.orders.find(x=>x.id===p.orderId);if(order){order.availability='Поставка получена';order.workHistory.unshift(`Закупка ${p.number} получена по накладной ${receiptNumber}`);put('orders')}}renderModule();notify(`Приходная накладная ${receiptNumber} проведена`)})}
function reports(){const sales=state.orders.reduce((s,x)=>s+x.sum,0),cost=state.orders.reduce((sum,o)=>sum+(o.items||[]).reduce((lineSum,line)=>{const product=state.catalog.find(p=>p.id==line.productId);return lineSum+(line.type==='Товар'?Number(product?.purchasePrice||0)*Number(line.qty||0):0)},0),0),paid=state.payments.reduce((s,x)=>s+(x.type==='Возврат'?-x.amount:x.amount),0),data=[['Продажи',M(sales)],['Прибыль',M(sales-cost)],['Себестоимость',M(cost)],['Остатки',state.catalog.reduce((s,x)=>s+(+x.stock||0),0)+' ед.'],['Движение товаров',state.serialUnits.reduce((s,x)=>s+x.events.length,0)],['Сотрудники',state.employees.length],['Приёмы',state.appointments.length],['Заказы',state.orders.length],['Оплаты',M(paid)],['Возвраты',state.payments.filter(x=>x.type==='Возврат').length],['Филиалы',new Set(state.appointments.map(x=>x.branch)).size],['Врачи',new Set(state.appointments.map(x=>x.doctor)).size]];return `<section class="card report-filterbar"><button class="secondary" data-report-export>Экспорт CSV</button><button class="primary" data-print>Печать</button></section><section class="report-grid">${data.map(x=>`<article class="card report-card"><small>${x[0]}</small><strong>${x[1]}</strong><p>Связанные актуальные данные</p></article>`).join('')}</section>`}
const oldRender=renderModule;renderModule=function(){const views={registry,prescriptions,lenscare:lenses,cash,serials,equipment,suppliers:procurementsView,invoices:receiptsView,reports};if(views[currentPage]){$('#moduleCreate').hidden=true;$('#moduleContent').innerHTML=views[currentPage]();bind()}else{oldRender();bind()}};const oldDetail=showDetail;showDetail=function(id){currentPage==='clients'?profile(id):oldDetail(id)};showOrder=orderDetail;
function searchAll(q){q=q.toLowerCase();const r=[];[['Клиент',state.clients],['Заказ',state.orders],['Рецепт',state.prescriptions],['Товар',state.catalog],['Серийный №',state.serialUnits]].forEach(([t,a])=>a.forEach(x=>JSON.stringify(x).toLowerCase().includes(q)&&r.push([t,x.name||x.client||x.number||x.serial,x])));$('#detailTitle').textContent='Глобальный поиск';$('#detailContent').innerHTML=`<div class="search-results">${r.slice(0,30).map(x=>`<button><small>${x[0]}</small><b>${E(x[1])}</b></button>`).join('')||'Ничего не найдено'}</div>`;detailDialog.showModal()}
function bind(){$$('[data-live]').forEach(i=>i.oninput=e=>$$('tbody tr',e.target.closest('.card')).forEach(r=>r.hidden=!r.textContent.toLowerCase().includes(e.target.value.toLowerCase())));$('[data-new-appointment]')?.addEventListener('click',()=>editAppointment());$$('[data-arrive]').forEach(b=>b.onclick=()=>{state.appointments.find(x=>x.id==b.dataset.arrive).status='Прибыл';put('appointments');renderModule()});$$('[data-start]').forEach(b=>b.onclick=()=>{state.appointments.find(x=>x.id==b.dataset.start).status='Приём начат';put('appointments');renderModule()});$$('[data-edit-appt]').forEach(b=>b.onclick=()=>editAppointment(state.appointments.find(x=>x.id==b.dataset.editAppt)));$('[data-new-rx]')?.addEventListener('click',()=>editRx());$$('[data-edit-rx]').forEach(b=>b.onclick=()=>editRx(state.prescriptions.find(x=>x.id==b.dataset.editRx)));$$('[data-delete-rx]').forEach(b=>b.onclick=()=>{if(confirm('Удалить рецепт?')){state.prescriptions=state.prescriptions.filter(x=>x.id!=b.dataset.deleteRx);put('prescriptions');renderModule()}});$('[data-new-lens]')?.addEventListener('click',()=>editLens());$$('[data-edit-lens]').forEach(b=>b.onclick=()=>editLens(state.lenses.find(x=>x.id==b.dataset.editLens)));$$('[data-remind]').forEach(b=>b.onclick=()=>{state.lenses.find(x=>x.id==b.dataset.remind).reminder='Отправлено';put('lenses');renderModule()});$$('[data-pay]').forEach(b=>b.onclick=()=>payment(b.dataset.pay));$$('[data-refund]').forEach(b=>b.onclick=()=>payment(b.dataset.refund,true));$$('[data-print],[data-order-print]').forEach(b=>b.onclick=()=>window.print());$$('[data-procure]').forEach(b=>b.onclick=()=>{const o=state.orders.find(x=>x.id==b.dataset.procure);state.procurements.unshift({id:Date.now(),number:'PO-'+Date.now().toString().slice(-4),orderId:o.id,product:o.product,supplier:'Основной поставщик',status:'Требуется заказать'});o.availability='Требуется заказать';put('procurements');put('orders');notify('Заявка поставщику создана')});$$('[data-serial]').forEach(b=>b.onclick=()=>{const x=state.serialUnits.find(x=>x.id==b.dataset.serial);$('#detailTitle').textContent=x.serial;$('#detailContent').innerHTML=timeline(x.events);detailDialog.showModal()});$$('[data-serial-op]').forEach(b=>b.onclick=()=>{const x=state.serialUnits.find(x=>x.id==b.dataset.serialOp);flow('Операция с единицей',`${sel('type','Операция',['Поступление','Перемещение','Резервирование','Продажа','Возврат'])}${fld('note','Локация / документ','text',x.location)}`,v=>{x.events.unshift([D(),v.type,v.note]);x.status=v.type==='Продажа'?'Продан':v.type==='Резервирование'?'В резерве':'В наличии';x.location=v.note;put('serialUnits');renderModule()})});$('[data-new-eq]')?.addEventListener('click',()=>editEq());$$('[data-edit-eq]').forEach(b=>b.onclick=()=>editEq(state.equipment.find(x=>x.id==b.dataset.editEq)));$('[data-kit]')?.addEventListener('click',()=>createKit());$('[data-report-export]')?.addEventListener('click',()=>downloadCsv())}
function kitProductSelect(name,label){return `<label>${label}<select name="${name}" required><option value="">Не выбрано</option>${state.catalog.map(x=>`<option value="${x.id}">${E(x.name)} · доступно ${Number(x.stock||0)}</option>`).join('')}</select></label>`}
function kitSerialSelect(name,label){return `<label>${label}<select name="${name}"><option value="">Не требуется</option>${state.serialUnits.filter(x=>x.status==='В наличии'&&!x.kitId).map(x=>`<option value="${x.id}">${E(x.serial)} · ${E(x.product)}</option>`).join('')}</select></label>`}
function createKit(){const employees=state.employees.map(x=>x.name),orders=state.orders.filter(x=>x.status!=='Черновик');flow('Сборка комплекта',`${fld('name','Название комплекта','text','','required')}${sel('direction','Направление',['Оптика','Слух','Протезирование','Ортопедия','Медтехника'])}${sel('warehouse','Склад',['Центральный склад','Медцентр Юнусабад','Магазин Чиланзар','Медцентр Самарканд'])}${sel('responsible','Ответственный',employees)}${linkedSelect('orderId','Связанный заказ',orders,'',x=>`№${x.id} · ${x.client} · ${x.product}`)}<h3 class="full">Компоненты</h3>${kitProductSelect('product1','Компонент 1')}${fld('qty1','Количество 1','number',1,'required min="1"')}${kitSerialSelect('serial1','Серийная единица 1')}${kitProductSelect('product2','Компонент 2')}${fld('qty2','Количество 2','number',1,'required min="1"')}${kitSerialSelect('serial2','Серийная единица 2')}${kitProductSelect('product3','Компонент 3')}${fld('qty3','Количество 3','number',1,'min="1"')}${kitSerialSelect('serial3','Серийная единица 3')}`,v=>{const components=[1,2,3].filter(i=>v[`product${i}`]).map(i=>({productId:+v[`product${i}`],qty:+v[`qty${i}`]||1,serialUnitId:v[`serial${i}`]?+v[`serial${i}`]:null}));if(components.length<2){notify('Выберите минимум два компонента');return false}const grouped={};components.forEach(x=>grouped[x.productId]=(grouped[x.productId]||0)+x.qty);const shortage=Object.entries(grouped).find(([id,qty])=>Number(state.catalog.find(x=>x.id==id)?.stock||0)<qty);if(shortage){const p=state.catalog.find(x=>x.id==shortage[0]);notify(`Недостаточно остатка: ${p?.name||shortage[0]}`);return false}const serialIds=components.map(x=>x.serialUnitId).filter(Boolean);if(new Set(serialIds).size!==serialIds.length){notify('Одну серийную единицу нельзя выбрать дважды');return false}for(const component of components){const product=state.catalog.find(x=>x.id===component.productId),unit=component.serialUnitId&&state.serialUnits.find(x=>x.id===component.serialUnitId);if(product.serial&&!unit){notify(`Для серийного товара «${product.name}» выберите конкретную единицу`);return false}if(unit&&unit.status!=='В наличии'){notify(`Серийная единица ${unit.serial} недоступна`);return false}if(unit&&unit.product!==product.name){notify(`Серийная единица ${unit.serial} не относится к товару «${product.name}»`);return false}component.name=product.name;component.serial=unit?.serial||''}const id=Date.now(),serial=`SET-${String(id).slice(-6)}`,barcode=`200${String(id).slice(-9)}`,order=state.orders.find(x=>x.id==v.orderId),at=new Date().toISOString();components.forEach(c=>{const product=state.catalog.find(x=>x.id===c.productId);product.stock=Number(product.stock||0)-c.qty;if(c.serialUnitId){const unit=state.serialUnits.find(x=>x.id===c.serialUnitId);unit.status='В составе комплекта';unit.parentKitId=id;unit.events.unshift([D(),'Включение в комплект',serial])}});const kit={id,name:v.name,direction:v.direction,warehouse:v.warehouse,responsible:v.responsible,orderId:v.orderId?+v.orderId:null,components,serial,barcode,status:'Собран',assembledAt:at,history:[{at,type:'Сборка',employee:v.responsible,note:components.map(x=>`${x.name} × ${x.qty}${x.serial?' · '+x.serial:''}`).join('; ')}]};state.kits.unshift(kit);state.serialUnits.unshift({id:id+1,kitId:id,serial,barcode,product:v.name,direction:v.direction,location:v.warehouse,status:'В наличии',client:order?.client||'—',orderId:kit.orderId,events:[[D(),'Сборка комплекта',kit.history[0].note]]});put('kits');put('catalog');put('serialUnits');renderModule();notify(`Комплект ${serial} создан и сохранён`)})}
function kitPassport(id){const kit=state.kits.find(x=>x.id===+id);if(!kit)return;$('#detailTitle').textContent=`Паспорт ${kit.serial}`;$('#detailContent').innerHTML=`<div class="detail-list">${[['Название',kit.name],['Направление',kit.direction],['Штрихкод',kit.barcode],['Склад',kit.warehouse],['Ответственный',kit.responsible],['Заказ',kit.orderId?`№${kit.orderId}`:'—'],['Статус',kit.status],['Собран',new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(kit.assembledAt))]].map(x=>`<div><small>${x[0]}</small><strong>${E(x[1])}</strong></div>`).join('')}</div><h3>Компоненты</h3><div class="order-lines">${kit.components.map(x=>`<div class="order-line"><span><b>${E(x.name)}</b><small>${x.serial?`Серия ${E(x.serial)} · `:''}${x.qty} шт.</small></span></div>`).join('')}</div>${timeline(kit.history.map(x=>[new Intl.DateTimeFormat(undefined,{dateStyle:'short',timeStyle:'short'}).format(new Date(x.at)),x.type,`${x.employee} · ${x.note}`]))}`;detailDialog.showModal()}
function disassembleKit(id){const kit=state.kits.find(x=>x.id===+id);if(!kit||kit.status!=='Собран')return;const reason=prompt(`Укажите причину разборки комплекта ${kit.serial}:`);if(!reason?.trim()){notify('Для разборки обязательна причина');return}if(!confirm(`Разобрать комплект ${kit.serial} и вернуть компоненты на склад ${kit.warehouse}?`))return;const at=new Date().toISOString();kit.components.forEach(c=>{const product=state.catalog.find(x=>x.id===c.productId);if(product)product.stock=Number(product.stock||0)+c.qty;if(c.serialUnitId){const unit=state.serialUnits.find(x=>x.id===c.serialUnitId);if(unit){unit.status='В наличии';delete unit.parentKitId;unit.location=kit.warehouse;unit.events.unshift([D(),'Возврат из комплекта',`${kit.serial} · ${reason.trim()}`])}}});kit.status='Разобран';kit.disassembledAt=at;kit.history.unshift({at,type:'Разборка',employee:state.profile?.name||'Текущий сотрудник',note:reason.trim()});const unit=state.serialUnits.find(x=>x.kitId===kit.id);if(unit){unit.status='Разобран';unit.events.unshift([D(),'Разборка комплекта',reason.trim()])}put('kits');put('catalog');put('serialUnits');renderModule();notify(`Комплект ${kit.serial} разобран, компоненты возвращены`)}
document.addEventListener('click',e=>{const button=e.target.closest('[data-kit-passport],[data-disassemble-kit]');if(!button)return;if(button.dataset.kitPassport)kitPassport(button.dataset.kitPassport);else disassembleKit(button.dataset.disassembleKit)})
document.addEventListener('click',e=>{const button=e.target.closest('[data-new-procurement],[data-procurement-detail],[data-procurement-status],[data-receive-procurement]');if(!button)return;if(button.dataset.newProcurement!==undefined)createProcurementFull();else if(button.dataset.procurementDetail)procurementDetail(button.dataset.procurementDetail);else if(button.dataset.procurementStatus)changeProcurementStatus(button.dataset.procurementStatus);else receiveProcurement(button.dataset.receiveProcurement)})
document.addEventListener('click',e=>{const button=e.target.closest('[data-open-shift],[data-close-shift],[data-cash-deposit],[data-cash-withdraw]');if(!button)return;if(button.dataset.openShift!==undefined)openCashShift();else if(button.dataset.closeShift!==undefined)closeCashShift();else if(button.dataset.cashDeposit!==undefined)cashMovement('Внесение');else cashMovement('Изъятие')})
const create=$('#moduleCreate');create.addEventListener('click',e=>{if(currentPage==='orders'){e.stopImmediatePropagation();$('#orderDialog').showModal()}},true);const gs=$('.topbar .search input');if(gs){gs.placeholder='Глобальный поиск: клиенты, заказы, рецепты, товары, серии';let t;gs.addEventListener('input',e=>{clearTimeout(t);if(e.target.value.length>1)t=setTimeout(()=>searchAll(e.target.value),400)},true)}
document.addEventListener('click',e=>{const button=e.target.closest('[data-repeat-appt],[data-rx-appt],[data-noshow-appt]');if(!button)return;const id=+(button.dataset.repeatAppt||button.dataset.rxAppt||button.dataset.noshowAppt),a=state.appointments.find(x=>x.id===id);if(button.dataset.repeatAppt){editAppointment({...a,id:undefined,date:D(),status:'Запланирован',results:'',diagnosis:'',assignments:''})}else if(button.dataset.rxAppt){editRx({clientId:a.clientId,client:a.client,doctor:a.doctor,appointmentId:a.id,date:a.date,status:'Черновик'})}else if(confirm(`Отметить неявку по записи №${a.id}?`)){a.status='Не пришёл';put('appointments');renderModule();notify('Неявка сохранена')}})
document.addEventListener('click',e=>{const button=e.target.closest('[data-print-rx]');if(!button)return;const r=state.prescriptions.find(x=>x.id==button.dataset.printRx);if(!r||!['Действует','Использован'].includes(r.status)){notify('Печать доступна только после подтверждения рецепта врачом');return}window.print()})
document.addEventListener('click',e=>{const button=e.target.closest('[data-send-lens-reminder],[data-confirm-lens],[data-repeat-lens]');if(!button)return;const id=+(button.dataset.sendLensReminder||button.dataset.confirmLens||button.dataset.repeatLens),x=state.lenses.find(y=>y.id===id);if(!x)return;if(button.dataset.sendLensReminder){if(!confirm(`Отправить клиенту ${x.client} напоминание о замене линз ${x.replace}?`))return;x.reminder='Отправлено';x.reminderSentAt=new Date().toISOString();put('lenses');renderModule();notify('Напоминание отправлено и сохранено')}else if(button.dataset.confirmLens){if(!confirm(`Сохранить подтверждение замены линз клиентом ${x.client}?`))return;x.clientConfirmedAt=new Date().toISOString();put('lenses');renderModule();notify('Подтверждение клиента сохранено')}else editLens({...x,id:undefined,fitted:D(),replace:'',reminder:'Запланировано',reminderSentAt:'',clientConfirmedAt:''})})
